  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:
    # Make a working copy
    df = df.copy()

    # Ensure numeric columns are numeric (coerce errors to NaN)
    num_cols = ['calworks', 'teachers', 'grades', 'rownames', 'expenditure', 'math', 'district', 'computer']
    for col in num_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    # Rename/derive clearer columns used in analysis
    # According to provided schema, 'calworks' corresponds to total enrollment.
    if 'calworks' in df.columns:
        df['Enrollment'] = df['calworks']
    else:
        # if Enrollment already present, keep it
        if 'Enrollment' not in df.columns:
            df['Enrollment'] = np.nan

    # Drop rows missing the essential variables needed to compute ratio and outcome
    required_for_ratio_and_outcome = ['Enrollment', 'teachers', 'grades', 'rownames']
    df = df.dropna(subset=required_for_ratio_and_outcome)

    # Prevent division by zero for teachers
    df.loc[df['teachers'] == 0, 'teachers'] = np.nan
    df = df.dropna(subset=['teachers'])

    # Compute Student-Teacher ratio
    df['StudentTeacherRatio'] = df['Enrollment'] / df['teachers']

    # Compute outcome: average of reading and math scores (columns: 'grades' = reading, 'rownames' = math per schema)
    df['AvgScore'] = df[['grades', 'rownames']].mean(axis=1)

    # Controls: map to clearer column names
    # 'math' column in schema appears to represent percent reduced-price lunch
    if 'math' in df.columns:
        df['PctReducedLunch'] = df['math']
    else:
        df['PctReducedLunch'] = np.nan

    # 'district' per schema is percent English learners
    if 'district' in df.columns:
        df['PctEnglishLearners'] = df['district']
    else:
        df['PctEnglishLearners'] = np.nan

    # Computers per classroom (or a computers indicator) - use 'computer' column if present
    if 'computer' in df.columns:
        df['ComputersPerClassroom'] = pd.to_numeric(df['computer'], errors='coerce')
    else:
        df['ComputersPerClassroom'] = np.nan

    # Keep the school categorical variable as-is for later encoding
    if 'school' not in df.columns:
        df['school'] = np.nan

    # Final set of columns to keep in transformed dataframe (keeps existing columns plus derived ones)
    keep_cols = list(df.columns)  # return full dataframe with new columns; model will select necessary columns

    return df
",
  "m_code": "def model(df: pd.DataFrame) -> any:
    import statsmodels.api as sm
    # Working copy
    df = df.copy()

    # Required model columns
    model_cols = ['AvgScore', 'StudentTeacherRatio', 'expenditure', 'PctReducedLunch', 'PctEnglishLearners', 'ComputersPerClassroom', 'Enrollment', 'school']

    # Ensure model columns exist
    missing = [c for c in model_cols if c not in df.columns]
    if missing:
        raise ValueError(f"Missing needed columns for modeling: {missing}")

    # Drop rows with missing data on model variables
    df_model = df.dropna(subset=['AvgScore', 'StudentTeacherRatio'])

    # For controls, allow some missing but drop rows that are missing core controls as well
    df_model = df_model.dropna(subset=['expenditure', 'PctReducedLunch', 'PctEnglishLearners', 'ComputersPerClassroom', 'Enrollment'])

    # Create design matrix X
    X = df_model[['StudentTeacherRatio', 'expenditure', 'PctReducedLunch', 'PctEnglishLearners', 'ComputersPerClassroom', 'Enrollment']].copy()

    # Encode categorical school variable using one-hot dummies (drop first to avoid multicollinearity)
    if 'school' in df_model.columns:
        dummies = pd.get_dummies(df_model['school'].astype(str), prefix='school', drop_first=True)
        if not dummies.empty:
            X = pd.concat([X, dummies], axis=1)

    # Add constant
    X = sm.add_constant(X, has_constant='add')

    # Dependent variable
    y = df_model['AvgScore']

    # Fit OLS model
    model_res = sm.OLS(y, X).fit()

    # Print a brief summary and return the full results object
    print(model_res.summary())
    return model_res
